export function paymentError(code: "timeout" | "declined") {
  if (code === "timeout") {
    return "Request timed out";
  }
  return "Payment declined";
}

export function shippingError(code: "timeout" | "lost") {
  if (code === "timeout") {
    return "Request timed out";
  }
  return "Package lost";
}
